import{_ as i}from"./chunks/teilleistungen-1-einrichten.DE0Eg8y5.js";import{_ as t,o as a,c as l,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/suchen-gruppenprozesse/gruppenprozesse-teilleistungsarten-aus-vorlage-02.png",o="/bilder/suchen-gruppenprozesse/gruppenprozesse-teilleistungsarten-aus-vorlage-03.png",g="/bilder/suchen-gruppenprozesse/gruppenprozesse-teilleistungsarten-aus-vorlage-04.png",T=JSON.parse('{"title":"Teilleistungsarten aus Fachvorlagen zuweisen","description":"","frontmatter":{"title":"Teilleistungsarten aus Fachvorlagen zuweisen","source_pageid":591,"source_revision":5363},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/teilleistungsarten-aus-vorlage-zuweisen-gruppenprozesse-teilleistungen.md","filePath":"schild3/suchen-gruppenprozesse/teilleistungsarten-aus-vorlage-zuweisen-gruppenprozesse-teilleistungen.md"}'),p={name:"schild3/suchen-gruppenprozesse/teilleistungsarten-aus-vorlage-zuweisen-gruppenprozesse-teilleistungen.md"};function d(h,r,c,m,z,b){return a(),l("div",null,[...r[0]||(r[0]=[s('<h1 id="teilleistungsarten-aus-fachvorlagen-zuweisen" tabindex="-1">Teilleistungsarten aus Fachvorlagen zuweisen <a class="header-anchor" href="#teilleistungsarten-aus-fachvorlagen-zuweisen" aria-label="Permalink to &quot;Teilleistungsarten aus Fachvorlagen zuweisen&quot;">​</a></h1><p>Übernehmen Sie die für Fach und Kursart vorbereiteten Teilleistungsarten in die ausgewählten Leistungsdaten. Bereiten Sie zuvor die Katalogeinträge und Fachzuordnungen vor.</p><p>Durch diesen Gruppenprozess können der ausgewählten Schülergruppe Teilleistungsarten aus einer Vorlage zugewiesen werden.</p><h2 id="vorarbeiten" tabindex="-1">Vorarbeiten <a class="header-anchor" href="#vorarbeiten" aria-label="Permalink to &quot;Vorarbeiten&quot;">​</a></h2><p>Legen Sie die benötigten Arten zuerst unter <strong>Kataloge ➜ Teilleistungsarten</strong> an. Ordnen Sie diese dann unter <strong>Kataloge ➜ Unterrichtsfächer</strong> den passenden Kombinationen aus Fach und Kursart zu.</p><p>Nach diesen Vorarbeiten weisen Sie die Vorlagen mit dem unten beschriebenen Gruppenprozess zu. Erst danach können die Noten für die einzelnen Teilleistungen eingetragen werden.</p><h3 id="vorbereitung-der-teilleistungsarten" tabindex="-1">Vorbereitung der Teilleistungsarten <a class="header-anchor" href="#vorbereitung-der-teilleistungsarten" aria-label="Permalink to &quot;Vorbereitung der Teilleistungsarten&quot;">​</a></h3><p><a href="/bilder/schueler/teilleistungen-1-einrichten.png"><img src="'+i+'" alt="Erstellen von Teilleistungsarten über Kataloge ➜ Teilleistungsarten." loading="lazy"></a></p><p><em>Erstellen von Teilleistungsarten über Kataloge ➜ Teilleistungsarten.</em></p><p>Bevor Teilleistungsarten individuellen Schülern und Kursen zugewiesen werden können, müssen die für die Schule gewünschten Teilleistungsarten, die erfasst und archiviert werden sollen, definiert werden.</p><p>Die für die Schule grundsätzlich zur Verfügung stehenden <em>Teilleistungen</em> werden über <em>Kataloge</em> ➜ <strong>Teilleistungsarten</strong> angelegt.</p><h3 id="zuweisung-zu-den-unterrichtsfachern" tabindex="-1">Zuweisung zu den Unterrichtsfächern <a class="header-anchor" href="#zuweisung-zu-den-unterrichtsfachern" aria-label="Permalink to &quot;Zuweisung zu den Unterrichtsfächern&quot;">​</a></h3><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-teilleistungsarten-aus-vorlage-02.png"><img src="'+u+'" alt="Zuweisung von Teilleistungsarten zu den Unterrichtsfächern über Kataloge ➜ Unterrichtsfächer." loading="lazy"></a></p><p><em>Zuweisung von Teilleistungsarten zu den Unterrichtsfächern über Kataloge ➜ Unterrichtsfächer.</em></p><p>Nach Erstellung des schulspezifischen Katalogs an Teilleistungsarten werden diese der entsprechenden Kombination aus Unterrichtsfach und Kursart zugeordnet.</p>',15),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n('Im Screenshot wurden dem Fach Deutsch für den "normalen" Klassenunterricht (PUK) die vorbereiteten Teilleistungsarten "SoLe X", für '),e("em",null,"Sonstige Leistungen"),n(', und "KA X", für '),e("em",null,"Klassenarbeiten"),n(", zugeordnet.")])],-1),s('<p>Zu berücksichtigen ist hier, dass nur den ausgewählten <em>Kursarten</em> die entsprechenden Teilleistungsarten zugeordnet werden.</p><p>Wird das Fach Deutsch im Beispiel also neben dem normalen Klassenunterricht an Schulen der Primar- und Sekundarstufe I auch zum Beispiel im Kursverband der Oberstufe (GKM, GKS o. ä.) unterrichtet, muss für <em>jede</em> dieser Kursarten die entsprechende Teilleistungsart aus der Vorlage zugewiesen werden.</p><p>Zur schnelleren Arbeit können Vorlagen auch kopiert und eingefügt werden.</p><h2 id="gruppenprozess-teilleistungsarten-aus-vorlage-zuweisen" tabindex="-1">Gruppenprozess &quot;Teilleistungsarten aus Vorlage zuweisen&quot; <a class="header-anchor" href="#gruppenprozess-teilleistungsarten-aus-vorlage-zuweisen" aria-label="Permalink to &quot;Gruppenprozess &quot;Teilleistungsarten aus Vorlage zuweisen&quot;&quot;">​</a></h2><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-teilleistungsarten-aus-vorlage-03.png"><img src="'+o+'" alt="Zuweisung von vorbereiteten Teilleistungsarten über Gruppenprozesse (Teilleistungen) ➜ Teilleistungen aus Vorlage zuweisen." loading="lazy"></a></p><p><em>Zuweisung von vorbereiteten Teilleistungsarten über Gruppenprozesse (Teilleistungen) ➜ Teilleistungen aus Vorlage zuweisen.</em></p><p>Im Reiter Gruppenprozesse kann schließlich über die Auswahl der Gruppe <em>Teilleistungen</em> und den Gruppenprozess <strong>Teilleistungen aus Vorlage zuweisen</strong> der aktuell ausgewählten Schülermenge im Container die vorbereiteten Teilleistungsarten zugewiesen werden.</p><p>Die Zuweisung orientiert sich dabei automatisch an der Kursart, in der das Fach bei den Schülern unterrichtet wird.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-teilleistungsarten-aus-vorlage-04.png"><img src="'+g+'" alt="Ansicht der eingetragenen Teilleistungsarten im aktuellen Abschnitt des Schülers." loading="lazy"></a></p><p><em>Ansicht der eingetragenen Teilleistungsarten im aktuellen Abschnitt des Schülers.</em></p><p>Im Beispiel sind den Schülern der Klasse 5a fünf vorbereitete Teilleistungsarten zugewiesen worden, die bei Klick auf das <strong>+</strong> beim Fach im <em>aktuellen Abschnitt</em> sichtbar werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Teilleistungsarten_aus_Vorlage_zuweisen_(Gruppenprozesse_Teilleistungen)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5363.</p>',13)])])}const _=t(p,[["render",d]]);export{T as __pageData,_ as default};
